// src/app/napp/base/EditorEvent.ts
var ActionData = class {
  enabled = true;
  target = "";
  component = "";
  action = "";
  value;
};
var Action = class {
  enabled = true;
  target;
  component;
  action = "";
  value;
  data;
  getData() {
    let data = new ActionData();
    data.enabled = this.enabled;
    data.component = this.component ? this.component?.name.toLocaleLowerCase() : "None";
    data.target = this.target ? this.target.uuid : "None";
    data.action = this.action;
    data.value = this.value;
    return data;
  }
};
var EventData = class {
  actions = [];
};
var EditorEvent = class {
  data;
  actions = [];
  getData() {
    let data = new EventData();
    this.actions.forEach((action) => {
      let actionData = action.getData();
      data.actions.push(actionData);
    });
    return data;
  }
  setData(data) {
    this.data = data;
    this.actions = data.actions.map((actionData) => {
      const action = new Action();
      action.action = actionData.action;
      action.enabled = actionData.enabled;
      action.value = actionData.value;
      action.data = actionData;
      this.actions.push(action);
      return action;
    });
  }
  resolveReferences(player) {
    return __async(this, null, function* () {
      for (const action of this.actions) {
        const target = player.findObjectByUUID(action.data.target);
        if (target) {
          action.target = target;
          if (action.data?.component != "") {
            action.component = target.components[action.data.component.toLowerCase()];
          }
        }
      }
    });
  }
  invoke() {
    for (const action of this.actions) {
      if (!action.enabled)
        continue;
      const target = action.component ?? action.target;
      if (!target)
        continue;
      const actions = target.getActions?.();
      const method = actions?.[action.action];
      if (method)
        method.invoke(target, action.value);
    }
  }
};

