      // Documentos y texto
      txt: "text/plain",
      html: "text/html",
      css: "text/css",
      js: "text/javascript",
      ts: "application/typescript",
      json: "application/json",
      ntarget: "application/json",
      xml: "application/xml",
      pdf: "application/pdf",
      csv: "text/csv",
      // Imágenes
      png: "image/png",
      jpg: "image/jpeg",
      jpeg: "image/jpeg",
      gif: "image/gif",
      svg: "image/svg+xml",
      webp: "image/webp",
      ico: "image/x-icon",
      // Audio y video
      mp3: "audio/mpeg",
      wav: "audio/wav",
      mp4: "video/mp4",
      ogg: "video/ogg",
      // 3D / Modelado
      gltf: "model/gltf+json",
      glb: "model/gltf-binary",
      obj: "text/plain",
      mtl: "text/plain",
      // Comprimidos
      zip: "application/x-zip-compressed",
      // WebAssembly
      wasm: "application/wasm",
      // Fuentes tipográficas
      ttf: "font/ttf",
      otf: "font/otf",
      woff: "font/woff",
      woff2: "font/woff2",
      eot: "application/vnd.ms-fontobject",
      fon: "application/x-font",
      // Por defecto
      default: "application/octet-stream"
