var Transform = class extends BaseComponent {
  position = new THREE2.Vector3(0, 0, 0);
  rotation = new THREE2.Vector3(0, 0, 0);
  scale = new THREE2.Vector3(1, 1, 1);
  constructor(obj) {
    super(obj);
    this.name = COMPONENT_NAME.TRANSFORM;
    this.type = COMPONENT_NAME.TRANSFORM;
  }
  addPositionAxis(val, axis) {
    this.position[axis] += val;
    if (this.obj.tObj) {
      this.obj.tObj.position[axis] += val;
      this.obj.tObj.updateMatrixWorld(true);
    }
  }
  addRotationAxis(val, axis) {
    this.rotation[axis] += val;
    if (this.obj.tObj) {
      this.obj.tObj.rotation[axis] += val;
      this.obj.tObj.updateMatrixWorld(true);
    }
  }
  setPosition(vec) {
    this.position.copy(vec);
    if (this.obj.tObj) {
      this.obj.tObj.position.copy(this.position);
      this.obj.tObj.updateMatrixWorld(true);
    }
  }
  setRotation(vec) {
    this.rotation.copy(vec);
    if (this.obj.tObj) {
      this.obj.tObj.rotation.copy(Utils.vector3ToEuler(this.rotation));
      this.obj.tObj.updateMatrixWorld(true);
    }
  }
  setScale(vec) {
    this.scale.copy(vec);
    if (this.obj.tObj) {
      this.obj.tObj.scale.copy(this.scale);
      this.obj.tObj.updateMatrixWorld(true);
    }
  }
  setWorldScale(vec) {
    const parentWorldScale = new THREE2.Vector3(1, 1, 1);
    const tObj = this.obj.tObj;
    if (tObj.parent) {
      tObj.parent.updateWorldMatrix(true, false);
      tObj.parent.getWorldScale(parentWorldScale);
    }
    const localScale = new THREE2.Vector3().copy(vec).divide(parentWorldScale);
    tObj.scale.copy(localScale);
    tObj.updateMatrix();
    tObj.updateMatrixWorld(true);
    this.updateFromTOBJ();
  }
  setWorldPosition(vec) {
    const tObj = this.obj.tObj;
    tObj.updateMatrixWorld(true);
    if (tObj.parent) {
      tObj.parent.updateMatrixWorld(true);
      const localPos = tObj.parent.worldToLocal(vec.clone());
      tObj.position.copy(localPos);
    } else {
      tObj.position.copy(vec);
    }
    tObj.updateMatrix();
    tObj.updateMatrixWorld(true);
    this.updateFromTOBJ();
  }
  setWorldRotation(quat) {
    const tObj = this.obj.tObj;
    const parentWorldQuat = new THREE2.Quaternion();
    if (tObj.parent) {
      tObj.parent.updateMatrixWorld(true);
      tObj.parent.getWorldQuaternion(parentWorldQuat);
    }
    const localQuat = new THREE2.Quaternion().copy(parentWorldQuat).invert().multiply(quat);
    tObj.quaternion.copy(localQuat);
    tObj.updateMatrix();
    tObj.updateMatrixWorld(true);
    const euler = new THREE2.Euler().setFromQuaternion(quat);
    this.rotation.copy(euler);
    this.updateFromTOBJ();
  }
  updateFromTOBJ() {
    this.position = this.obj.tObj.position.clone();
    this.rotation = Utils.eulerToVector3(this.obj.tObj.rotation.clone());
    this.scale = this.obj.tObj.scale.clone();
  }
};
