// src/app/napp/components/AudioSource.ts
import * as THREE6 from "./deps/three.js";
var AudioSource = class extends BaseComponent {
  clip;
  sound;
  autoplay = true;
  loop = false;
  volume = 1;
  isPlaying = false;
  isPaused = false;
  constructor(obj) {
    super(obj);
    this.type = COMPONENT_TYPE.AUDIO;
    this.name = COMPONENT_NAME.AUDIO_SOURCE;
    this.sound = new THREE6.Audio(obj.player.audioListener);
  }
  setAudioClip(asset) {
    this.clip = asset;
    this.sound.setBuffer(this.clip.clip);
  }
  setAutoPlay(value) {
    this.autoplay = value;
  }
  setLoop(value) {
    this.loop = value;
    this.sound.setLoop(value);
  }
  setVolume(value) {
    this.volume = value;
    this.sound.setVolume(value);
  }
  play() {
    if (!this.obj.player.isPlaying) {
      return;
    }
    if (this.isPlaying) {
      this.stop();
    }
    this.isPlaying = true;
    this.isPaused = false;
    this.sound.play();
  }
  pause() {
    if (!this.isPlaying) {
      return;
    }
    this.isPlaying = false;
    this.isPaused = true;
    this.sound.pause();
    console.log("pausseeeee");
  }
  stop() {
    if (!this.sound.source) {
      return;
    }
    console.log("Stoooop");
    this.isPlaying = false;
    this.sound.stop();
  }
  onStart() {
    this.setLoop(this.loop);
    this.setVolume(this.volume);
    if (this.autoplay) {
      this.play();
    }
  }
  onStop() {
    this.stop();
  }
  onPause() {
    this.pause();
  }
  onUnpause() {
    if (this.isPaused) {
      this.play();
    }
  }
  onEnable() {
    this.obj.activeInHierarchy = this.obj.isActiveInHierarchy();
    if (this.obj.activeInHierarchy) {
      this.onStart();
    }
  }
  onDisable() {
    this.stop();
  }
};
AudioSource.props = {
  clip: {
    type: "asset",
    visible: true,
    support: [COMPONENT_TYPE.AUDIO],
    set(i, asset) {
      i.setAudioClip(asset);
    }
  },
  autoplay: {
    type: "bool",
    visible: true,
    default: true
  },
  loop: {
    type: "bool",
    visible: true,
    default: false
  },
  volume: {
    type: "number",
    visible: true,
    min: 0,
    step: 0.1,
    isFloat: true,
    default: 1
  }
};
AudioSource.actions = {
  play: {
    name: "play",
    invoke: (instance) => {
      instance.play();
    }
  },
  playDelayed: {
    name: "playDelayed",
    param: {
      type: "number",
      visible: true,
      isFloat: true,
      step: 0.1,
      min: 0,
      set(instance, value) {
        instance.value = value;
      },
      get(instance) {
        return instance.value;
      }
    },
    invoke: (instance, value) => {
      setTimeout(() => {
        instance.play();
      }, value * 1e3);
    }
  },
  setVolume: {
    name: "setVolume",
    param: {
      type: "number",
      visible: true,
      isFloat: true,
      step: 0.1,
      min: 0,
      set(instance, value) {
        instance.value = value;
      },
      get(instance) {
        return instance.value;
      }
    },
    invoke: (instance, value) => {
      instance.setVolume(value);
    }
  }
};

