import * as THREE7 from "./deps/three.js";
var MeshRenderer = class extends BaseComponent {
  material;
  originalMaterial;
  invisibleMaterial;
  constructor(obj) {
    super(obj);
    this.name = COMPONENT_NAME.MESH_RENDERER;
    this.type = COMPONENT_TYPE.RENDERER;
    this.invisibleMaterial = new THREE7.MeshBasicMaterial({ color: "rgb(0, 0, 0)", transparent: true, opacity: 0 });
  }
  setEnabled(enabled) {
    super.setEnabled(enabled);
    if (!enabled) {
      this.originalMaterial = this.obj.tObj.material;
      this.obj.tObj.material = this.invisibleMaterial;
    } else {
      if (this.originalMaterial) {
        this.obj.tObj.material = this.originalMaterial;
      }
    }
  }
  setMaterial(material) {
    this.material = material;
    if (this.obj.tObj) {
      this.obj.tObj.material = material.material;
    }
  }
};
MeshRenderer.props = {
  material: {
    type: "asset",
    visible: true,
    support: [ASSET_TYPE.MATERIAL],
    set: (instance, asset) => instance.setMaterial(asset)
  }
};

// src/app/napp/components/Button3D.ts
var Button3D = class extends BaseComponent {
  interactable = true;
  clickEvent = new EditorEvent();
  event = "Click";
  downDetected = false;
  constructor(obj) {
    super(obj);
    this.type = COMPONENT_NAME.BUTTON3D;
    this.name = COMPONENT_NAME.BUTTON3D;
  }
  setInteractable(value) {
    this.interactable = value;
    if (!this.obj.player.isPlaying) {
      return;
    }
    if (this.interactable) {
      this.obj.player.raycaster?.addTarget(this.obj.tObj);
    } else {
      this.obj.player.raycaster?.removeTarget(this.obj.tObj);
    }
  }
  onEnable() {
    if (!this.obj.activeInHierarchy) {
      return;
    }
    this.setInteractable(this.interactable);
  }
  onDisable() {
    this.obj.player.raycaster?.removeTarget(this.obj.tObj);
  }
  onStart() {
    if (!this.obj.activeInHierarchy) {
      this.obj.player.raycaster?.removeTarget(this.obj.tObj);
    }
  }
  // override onStop(): void { this.obj.player.raycaster?.removeTarget(this.obj.tObj); }
  onPointerDown(event) {
    if (this.clickEvent && typeof this.clickEvent.invoke === "function") {
      if (this.event == "PointerDown") {
        this.clickEvent.invoke();
        event.stopPropagation();
        console.log("Button pointerdown", this.obj.name, this.clickEvent.getData());
      } else if (this.event == "Click") {
        this.downDetected = true;
      }
    }
  }
  onPointerUp(event) {
    if (this.clickEvent && typeof this.clickEvent.invoke === "function" && this.downDetected) {
      this.clickEvent.invoke();
      event.stopPropagation();
      console.log("Button clicked", this.obj.name, this.clickEvent.getData());
    }
  }
};
Button3D.props = {
  interactable: {
    type: "bool",
    visible: true,
    default: true,
    set: (instance, value) => {
      instance.setInteractable(value);
    }
  },
  event: {
    type: "select",
    visible: true,
    options: ["Click", "PointerDown"]
    // set: (instance: Button, value: string) => instance.setEnviroment(value),
    // get: (instance: SceneAsset) => instance.environment
  },
  clickEvent: {
    type: "event",
    name: "OnClick",
    visible: true,
    hideLabel: true,
    supportTypes: ["SceneObject"],
    // set: (instance: Button3D, value: EventData) => { instance.clickEvent.setData(value, instance.obj.player); },
    get: (instance) => {
      return instance.clickEvent.getData();
    }
  }
};

