// src/app/napp/components/Timer.ts
var Timer = class extends BaseComponent {
  time = 0;
  // Duración total
  autoplay = false;
  loop = false;
  onTime;
  elapsed = 0;
  // Tiempo acumulado
  isPlaying = false;
  constructor(obj) {
    super(obj);
    this.onTime = new EditorEvent();
    this.name = COMPONENT_NAME.TIMER;
  }
  onStart() {
    if (this.autoplay) {
      this.play();
    }
  }
  play() {
    this.isPlaying = true;
  }
  pause() {
    this.isPlaying = false;
  }
  stop() {
    this.isPlaying = false;
    this.elapsed = 0;
    this.name = COMPONENT_NAME.TIMER;
  }
  onUpdate(delta) {
    if (!this.isPlaying || this.time < 0)
      return;
    this.elapsed += delta;
    this.name = `${COMPONENT_NAME.TIMER} (${Math.round(this.elapsed * 10) / 10})`;
    if (this.elapsed >= this.time) {
      this.onTime.invoke();
      if (this.loop) {
        this.elapsed = 0;
      } else {
        this.isPlaying = false;
        this.name = COMPONENT_NAME.TIMER;
        this.stop();
      }
    }
  }
};
Timer.props = {
  time: {
    type: "number",
    isFloat: true,
    visible: true
  },
  autoplay: {
    type: "bool",
    visible: true
  },
  loop: {
    type: "bool",
    visible: true
  },
  onTime: {
    type: "event",
    name: "OnTime",
    visible: true,
    hideLabel: true,
    get: (instance) => {
      return instance.onTime.getData();
    }
  }
};
Timer.actions = {
  play: {
    name: "play",
    invoke: (instance) => {
      instance.play();
    }
  }
};

