// src/app/napp/components/Message.ts
var Message = class extends BaseComponent {
  test = "";
  match = "None";
  onMessage;
  constructor(obj) {
    super(obj);
    this.name = "Message";
    this.type = "Message";
    this.onMessage = new EditorEvent();
  }
  onStart() {
    if (this.obj.player.editor && this.test != "") {
      if (this.test == this.match) {
        console.log(`Testing Message (${this.match})`);
        this.onMessage.invoke();
      }
      return;
    }
  }
  checkMessage(val) {
    if (val != this.match) {
      return;
    }
    console.log(`Running Message (${this.match})`);
    this.onMessage.invoke();
  }
};
Message.props = {
  test: {
    type: "string",
    visible: true
  },
  match: {
    type: "string",
    visible: true
  },
  onMessage: {
    type: "event",
    name: "OnMessage",
    visible: true,
    hideLabel: true,
    get: (instance) => instance.onMessage.getData()
  }
};
Message.actions = {
  checkMessage: {
    name: "checkMessage",
    param: {
      type: "bool",
      visible: true,
      set(instance, value) {
        instance.value = value;
      },
      get(instance) {
        return instance.value;
      }
    },
    invoke: (instance, value) => {
      instance.checkMessage(value);
    }
  }
};

