// src/app/napp/assets/FontAsset.ts
import * as THREE30 from "./deps/three.js";
var FontAsset = class extends Asset {
  fontFamily = "Arial";
  constructor(player, file) {
    super(player, file);
    this.type = ASSET_TYPE.FONT;
    this.uuid = THREE30.MathUtils.generateUUID();
    this.injectFontStyle();
  }
  // override load(): Promise<void> {
  // }
  injectFontStyle() {
    if (!this.url)
      return;
    const fontName = this.name.replace(/-/g, "_");
    this.fontFamily = `${fontName}`;
    const styleId = `font-style-${fontName}`;
    let element = document.getElementById(styleId);
    if (!element) {
      const style = document.createElement("style");
      style.id = styleId;
      style.textContent = `
                @font-face {
                    font-family: '${this.fontFamily}';
                    src: url('${this.url}');
                }
            `;
      document.head.appendChild(style);
    }
    console.log(element);
  }
};

// src/app/napp/assets/CSSAsset.ts
var CSSAsset = class extends Asset {
  styleElement = null;
  constructor(player, file) {
    super(player, file);
    this.type = ASSET_TYPE.CSS;
  }
  load() {
    return __async(this, null, function* () {
      const reader = new FileReader();
      reader.onload = (e) => {
        this.fileContent = e.target?.result;
        this.inject(this.fileContent);
        ;
      };
      reader.onerror = (e) => {
        console.error("Error al leer el archivo CSS:", e);
      };
      reader.readAsText(this.file);
    });
  }
  inject(styleText) {
    const cssId = `css-${this.file.name}`;
    let styleElement = document.getElementById(cssId);
    if (!styleElement) {
      styleElement = document.createElement("style");
      styleElement.type = "text/css";
      styleElement.id = cssId;
      document.head.appendChild(styleElement);
    }
    styleElement.textContent = styleText;
    this.styleElement = styleElement;
    console.log("Estilos inyectados:", styleElement);
  }
};

